const TAMANHO = { mensal: 7, diaria: 10, horaria: 13 }

function chaveDeExecucao(nome, periodicidade, momento) {
  if (!nome) return null

  const corte = TAMANHO[periodicidade]
  if (!corte) return null

  return `${nome}:${String(momento).slice(0, corte)}`
}
